"""Report fresh-seed confirmation without reading detector-validation labels."""
from pathlib import Path
import json,hashlib
H=Path(__file__).resolve().parent;N=H.parent/'softplay_capacity_confirmation_20260910'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    d=json.loads((N/'diagnostics.json').read_text());plan=json.loads((N/'study-plan.json').read_text());pp=json.loads((N/'fresh/pilot-plan.json').read_text())
    for name,h in pp['source_hashes'].items():assert sha(N/'fresh'/name)==h==sha(H/'b0_capacity'/name)
    assert all(sha(H.parents[1]/p)==v for p,v in plan['protected'].items());v=d['results']['fresh'];replay=json.loads((N/'fresh/intervention-replay-audit.json').read_text());audit=json.loads((N/'fresh/pilot-audit.json').read_text())
    out={'fresh_seed_confirmation':True,'passes_realism':v['realism_gate_passed'],'source_auc':v['source_auc'],'preflop_call_rate':v['action_summary']['preflop']['equal_pair_mean_fold_check_call_raise'][2],'call_strength':v['conditional']['preflop_calls']['own_strength'],'supported_pairs':v['supported_pairs'],'all_generator_bytes_unchanged':True,'hands':audit['hands'],'replayed_hands':replay['hands'],'changed_actions_verified':replay['counterfactual_action_changes_verified'],'controller_input_parity_rows':d['controller_feature_parity_rows'],'no_outer_held_access':True,'protected_submissions_unchanged':True,'next_step':'Freeze detector utility with original-only and several matched resampling draws across three seeds and all four populations.' if v['realism_gate_passed'] else 'Do not fit utility models. Diagnose why unchanged generator does not replicate in the fresh population, using training-only evidence.'};(N/'summary.json').write_text(json.dumps(out,indent=2))
    text='# Fresh-seed capacity-policy confirmation\n\n'+('PASS' if out['passes_realism'] else 'FAIL')+' under the unchanged realism rule.\n\n'+f"Source AUC {out['source_auc']:.6f}; preflop calling {out['preflop_call_rate']:.6f}; call strength {out['call_strength']:.6f}; {out['supported_pairs']} supported target pairs. All 96,000 hands pass accounting/label checks, and {out['changed_actions_verified']:,} changed actions are independently replayed. Generator code, model, ordinary policies and environment bytes match the development trial.\n\n"+out['next_step']+'\n\nThe simulation seeds are fresh. Learned policies and original training references are shared, so this is not a new real-world data source. No outer-held utility scoring, VM use or submission occurred.\n';(N/'RESULTS.md').write_text(text,encoding='utf-8');print(json.dumps(out,indent=2))
if __name__=='__main__':main()
